import React, { useCallback, useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { authApis, endpoints } from "../configs/Apis";
import { getApiError } from "../utils/apiError";
import useNotificationState from "../utils/useNotificationState";
import { formatIsoDate } from "../utils/date";
import AutoDismissMessage from "../components/AutoDismissMessage";
import MoneyInput from "../components/MoneyInput";
import SearchableDropdown from "../components/SearchableDropdown";
import ConfirmDialog from "../components/ConfirmDialog";
import Skeleton from "../components/Skeleton";
import "../css/Promotions.css";

const EMPTY_FORM = {
  name: "",
  condition_type: "min_quantity",
  min_quantity: "",
  min_order_amount: "",
  start_date: "",
  end_date: "",
  discount_type: "fixed_amount",
  discount_value: "",
  max_discount_amount: "",
};

const CONDITION_OPTIONS = [
  { value: "min_quantity", label: "Mua đủ số lượng sản phẩm" },
  { value: "min_order_amount", label: "Đơn đạt giá trị tối thiểu" },
  { value: "holiday", label: "Theo dịp / ngày lễ" },
];

const DISCOUNT_OPTIONS = [
  { value: "fixed_amount", label: "Giảm số tiền cố định" },
  { value: "percentage", label: "Giảm theo phần trăm" },
];

function formatDate(value) {
  return formatIsoDate(value, { empty: "Không giới hạn", invalid: value });
}

function PromotionForm({ promotion, onClose, onSaved }) {
  const [form, setForm] = useState(() =>
    promotion
      ? {
          name: promotion.name || "",
          condition_type: promotion.condition_type || "min_quantity",
          min_quantity: String(promotion.min_quantity || ""),
          min_order_amount: String(promotion.min_order_amount || ""),
          start_date: promotion.start_date || "",
          end_date: promotion.end_date || "",
          discount_type: promotion.discount_type || "fixed_amount",
          discount_value: String(promotion.discount_value || ""),
          max_discount_amount: String(promotion.max_discount_amount || ""),
        }
      : EMPTY_FORM,
  );
  const [saving, setSaving] = useState(false);
  const [error, setError] = useNotificationState();

  const update = (field, value) => {
    setForm((current) => ({ ...current, [field]: value }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError("");
    const payload = {
      ...form,
      min_quantity:
        form.condition_type === "min_quantity"
          ? Number(form.min_quantity)
          : null,
      min_order_amount:
        form.condition_type === "min_order_amount"
          ? Number(form.min_order_amount)
          : null,
      start_date: form.start_date || null,
      end_date: form.end_date || null,
      discount_value: Number(form.discount_value),
      max_discount_amount:
        form.discount_type === "percentage" && form.max_discount_amount
          ? Number(form.max_discount_amount)
          : null,
    };
    try {
      setSaving(true);
      const response = promotion
        ? await authApis().put(endpoints.promotionDetail(promotion.id), payload)
        : await authApis().post(endpoints.promotions, payload);
      onSaved(response.data?.promotion);
    } catch (requestError) {
      setError(getApiError(requestError));
    } finally {
      setSaving(false);
    }
  };

  return createPortal(
    <div className="promotion-modal-overlay">
      <div
        className="promotion-modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="promotion-form-title"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="promotion-modal-header">
          <div>
            <p>{promotion ? "CHỈNH SỬA" : "TẠO MỚI"}</p>
            <h2 id="promotion-form-title">
              {promotion ? promotion.name : "Chương trình khuyến mãi"}
            </h2>
          </div>
          <button type="button" onClick={onClose} aria-label="Đóng">
            ×
          </button>
        </div>
        <form className="promotion-form" onSubmit={handleSubmit}>
          <AutoDismissMessage message={error} className="promotion-alert" />
          <label className="promotion-field promotion-field-wide">
            <span>Tên chương trình</span>
            <input
              value={form.name}
              onChange={(event) => update("name", event.target.value)}
              placeholder="Ví dụ: Khuyến mãi Quốc khánh"
              maxLength="150"
              required
            />
          </label>

          <label className="promotion-field">
            <span>Điều kiện áp dụng</span>
            <SearchableDropdown
              value={form.condition_type}
              onChange={(value) => update("condition_type", value)}
              options={CONDITION_OPTIONS}
              ariaLabel="Điều kiện áp dụng"
            />
          </label>

          {form.condition_type === "min_quantity" && (
            <label className="promotion-field">
              <span>Số sản phẩm cần mua để có thể áp dụng khuyến mãi</span>
              <input
                type="number"
                min="1"
                step="1"
                value={form.min_quantity}
                onChange={(event) => update("min_quantity", event.target.value)}
                placeholder="Ví dụ: 10"
                required
              />
            </label>
          )}

          {form.condition_type === "min_order_amount" && (
            <label className="promotion-field">
              <span>Giá trị đơn tối thiểu</span>
              <MoneyInput
                value={form.min_order_amount}
                onChange={(value) => update("min_order_amount", value)}
                label="Giá trị đơn tối thiểu"
                placeholder="Ví dụ: 5.000.000"
                required
              />
            </label>
          )}

          <label className="promotion-field">
            <span>
              Ngày bắt đầu
              {form.condition_type !== "holiday" ? " (không bắt buộc)" : ""}
            </span>
            <input
              type="date"
              value={form.start_date}
              onChange={(event) => update("start_date", event.target.value)}
              required={form.condition_type === "holiday"}
            />
          </label>
          <label className="promotion-field">
            <span>
              Ngày kết thúc
              {form.condition_type !== "holiday" ? " (không bắt buộc)" : ""}
            </span>
            <input
              type="date"
              value={form.end_date}
              onChange={(event) => update("end_date", event.target.value)}
              required={form.condition_type === "holiday"}
            />
          </label>

          <label className="promotion-field promotion-discount-field">
            <span>Cách giảm</span>
            <SearchableDropdown
              value={form.discount_type}
              onChange={(value) => update("discount_type", value)}
              options={DISCOUNT_OPTIONS}
              ariaLabel="Cách giảm"
            />
          </label>
          <label className="promotion-field">
            <span>
              {form.discount_type === "percentage"
                ? "Phần trăm giảm"
                : "Số tiền giảm"}
            </span>
            {form.discount_type === "percentage" ? (
              <input
                type="number"
                inputMode="decimal"
                min="0.01"
                max="100"
                step="0.01"
                value={form.discount_value}
                onChange={(event) =>
                  update("discount_value", event.target.value)
                }
                placeholder="Ví dụ: 10"
                required
              />
            ) : (
              <MoneyInput
                value={form.discount_value}
                onChange={(value) => update("discount_value", value)}
                label="Số tiền giảm"
                placeholder="Ví dụ: 100.000"
                required
              />
            )}
          </label>

          {form.discount_type === "percentage" && (
            <label className="promotion-field promotion-field-wide">
              <span>Mức giảm tối đa (không bắt buộc)</span>
              <MoneyInput
                value={form.max_discount_amount}
                onChange={(value) => update("max_discount_amount", value)}
                label="Mức giảm tối đa"
                allowEmpty
                placeholder="Để trống nếu không giới hạn"
              />
            </label>
          )}

          <div className="promotion-form-actions promotion-field-wide">
            <button type="button" onClick={onClose} disabled={saving}>
              Hủy
            </button>
            <button type="submit" className="is-primary" disabled={saving}>
              {saving
                ? "Đang lưu..."
                : promotion
                  ? "Lưu thay đổi"
                  : "Tạo khuyến mãi"}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body,
  );
}

function Promotions() {
  const [promotions, setPromotions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useNotificationState();
  const [success, setSuccess] = useNotificationState();
  const [editingPromotion, setEditingPromotion] = useState(null);
  const [formOpen, setFormOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleting, setDeleting] = useState(false);
  const currentUser = (() => {
    try {
      return JSON.parse(localStorage.getItem("user")) || {};
    } catch {
      return {};
    }
  })();

  const fetchPromotions = useCallback(async () => {
    try {
      setLoading(true);
      setError("");
      const response = await authApis().get(endpoints.promotions);
      setPromotions(response.data?.promotions || []);
    } catch (requestError) {
      setError(getApiError(requestError));
    } finally {
      setLoading(false);
    }
  }, [setError]);

  useEffect(() => {
    if (currentUser.role === "quản lý") fetchPromotions();
  }, [currentUser.role, fetchPromotions]);

  const handleSaved = (promotion) => {
    setFormOpen(false);
    setEditingPromotion(null);
    setSuccess(
      promotion?.id === editingPromotion?.id
        ? "Đã cập nhật khuyến mãi."
        : "Đã tạo khuyến mãi.",
    );
    fetchPromotions();
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    try {
      setDeleting(true);
      await authApis().delete(endpoints.promotionDetail(deleteTarget.id));
      setDeleteTarget(null);
      setSuccess("Đã xóa khuyến mãi. Các đơn cũ vẫn giữ thông tin đã áp dụng.");
      fetchPromotions();
    } catch (requestError) {
      setError(getApiError(requestError));
    } finally {
      setDeleting(false);
    }
  };

  if (currentUser.role !== "quản lý") {
    return (
      <div className="promotions-page">
        <div className="promotion-empty">
          Bạn không có quyền quản lý khuyến mãi.
        </div>
      </div>
    );
  }

  return (
    <div className="promotions-page">
      <header className="promotions-header">
        <div>
          <h1>Khuyến mãi</h1>
          <p>
            Thiết lập điều kiện và mức giảm dùng thống nhất khi lập đơn bán
            hàng.
          </p>
        </div>
        <button
          type="button"
          onClick={() => {
            setEditingPromotion(null);
            setFormOpen(true);
          }}
        >
          + Tạo khuyến mãi
        </button>
      </header>
      <AutoDismissMessage message={error} className="promotion-alert" />
      <AutoDismissMessage message={success} type="success" role="status" className="promotion-success" />

      <div className="promotions-card">
        {loading ? (
          <Skeleton rows={5} columns={5} />
        ) : promotions.length ? (
          <div className="promotions-table-wrap">
            <table className="promotions-table">
              <thead>
                <tr>
                  <th>Chương trình</th>
                  <th>Điều kiện</th>
                  <th>Mức khuyến mãi</th>
                  <th>Thời gian</th>
                  <th aria-label="Thao tác" />
                </tr>
              </thead>
              <tbody>
                {promotions.map((promotion) => (
                  <tr key={promotion.id}>
                    <td>
                      <strong>{promotion.name}</strong>
                    </td>
                    <td>{promotion.condition_summary}</td>
                    <td>
                      <strong className="promotion-benefit">
                        {promotion.benefit_summary}
                      </strong>
                    </td>
                    <td>
                      {promotion.start_date || promotion.end_date
                        ? `${formatDate(promotion.start_date)} → ${formatDate(promotion.end_date)}`
                        : "Không giới hạn"}
                    </td>
                    <td>
                      <div className="promotion-row-actions">
                        <button
                          type="button"
                          onClick={() => {
                            setEditingPromotion(promotion);
                            setFormOpen(true);
                          }}
                        >
                          Chỉnh sửa
                        </button>
                        <button
                          type="button"
                          className="is-danger"
                          onClick={() => setDeleteTarget(promotion)}
                        >
                          Xóa
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="promotion-empty">
            Chưa có chương trình khuyến mãi. Hãy tạo chương trình đầu tiên.
          </div>
        )}
      </div>

      {formOpen && (
        <PromotionForm
          promotion={editingPromotion}
          onClose={() => {
            setFormOpen(false);
            setEditingPromotion(null);
          }}
          onSaved={handleSaved}
        />
      )}
      <ConfirmDialog
        open={Boolean(deleteTarget)}
        title="Xóa khuyến mãi?"
        message={
          deleteTarget
            ? `Khuyến mãi “${deleteTarget.name}” sẽ không thể áp dụng cho đơn mới. Các đơn cũ vẫn giữ nguyên lịch sử.`
            : ""
        }
        confirmLabel="Xóa khuyến mãi"
        cancelLabel="Quay lại"
        danger
        loading={deleting}
        onConfirm={handleDelete}
        onCancel={() => {
          if (!deleting) setDeleteTarget(null);
        }}
      />
    </div>
  );
}

export default Promotions;
